WITH parsed AS (SELECT id, log_ts, latency_ms, context, COALESCE(context['trace'], 'none') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT id, log_ts, latency_ms, trace_or_default, COUNT(latency_ms) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) latency_ms_count_2h, PERCENT_RANK() OVER (ORDER BY latency_ms DESC) latency_ms_percent_rank, FIRST_VALUE(trace_or_default) IGNORE NULLS OVER (ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_trace_or_default FROM parsed WHERE latency_ms < 643
